select * from customer_shopping cs 


--The total revenue generated by male vs. female customers
select
sum(purchase_amount),
gender
from customer_shopping cs
group by cs.gender 

--Customers used a discount but still spent more than the average purchase amount
select
customer_id,
purchase_amount
from customer_shopping cs 
where cs.discount_applied ='Yes' and cs.purchase_amount >= (
select 
avg(cs.purchase_amount)
from customer_shopping cs
)

--Top 5 products with the highest average review rating
select
item_purchased as product,
round(avg(review_rating::numeric),2) as average_review_rating
from customer_shopping cs 
group by cs.item_purchased 
order by average_review_rating desc
limit 5

--The average Purchase Amounts between Standard and Express Shipping.
select
round(avg(purchase_amount),2),
shipping_type
from customer_shopping cs 
where shipping_type in ('Express','Standard')
group by cs.shipping_type 
 
--The average spend and total revenue between subscribers and non-subscribers.
select 
cs.subscription_status,
count(cs.customer_id),
avg(cs.purchase_amount) as average_spend,
sum(cs.purchase_amount) as total_revenue
from customer_shopping cs
group by cs.subscription_status 
order by average_spend desc, total_revenue desc

--Top 5 products have the highest percentage of purchases with discount applied
select  
item_purchased,
round(100.0 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) AS discount_rate
from customer_shopping cs 
group by item_purchased
order by discount_rate desc
limit 5;


--Segmenting customers into New, Returning and loyal based on their previous number of purchases, 
--and showing the count of each segment.
select
cs_2.customer_segment ,
count(*)
from
(
select 
cs.customer_id,
cs.previous_purchases ,
case 
	when previous_purchases =1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal'
end as customer_segment
from customer_shopping cs 
) as cs_2
group by customer_segment

--The top 3 most purchased products within each category
with item_counts as (
select 
category,
item_purchased,
count(cs.customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customer_shopping cs 
group by category, item_purchased
) 
select
item_rank,
category,
item_purchased,
total_orders 
from item_counts 
where item_rank <=3

--Customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe
select 
count(customer_id) as repeat_buyers,
subscription_status
from customer_shopping cs 
where cs.previous_purchases >5
group by cs.subscription_status 

--The revenue contribution of each age group
select cs.age_group ,
sum(purchase_amount) as total_revenue
from customer_shopping cs 
group by age_group 
order by sum(purchase_amount) desc













